using UnityEngine;
[DefaultExecutionOrder(600),DisallowMultipleComponent]public sealed class E162R3HeadAperture:MonoBehaviour{
 public E158NativeEyeProviders nativeEye;public Vector3 centreHead0,centreHead1;public Vector4 scale=new Vector4(1.2f,1.15f,0,0);public bool apertureEnabled=true,playing=true,continuous=true;public float speed=1,cycleSeconds=3;public int poseIndex;public float pathT;public Matrix4x4 lastHeadToWorld,lastWorldToHead;MaterialPropertyBlock block;int count;float elapsed;static readonly Vector3[]pathKeys={Vector3.zero,new Vector3(4,8,0),new Vector3(4,-8,0),Vector3.zero};
 public void Initialize(Vector3 world0,Vector3 world1){centreHead0=nativeEye.head.InverseTransformPoint(world0);centreHead1=nativeEye.head.InverseTransformPoint(world1);Apply();}
 public void SetPose(int index){poseIndex=((index%3)+3)%3;nativeEye.SetGaze(0);nativeEye.SetPose(poseIndex);Apply();}
 public void SetPath(float t){pathT=Mathf.Repeat(t,1);float k=pathT*3;int segment=Mathf.FloorToInt(k);Vector3 e=Vector3.Lerp(pathKeys[segment],pathKeys[segment+1],k-segment);nativeEye.head.localRotation=nativeEye.neutralHeadLocalRotation*Quaternion.Euler(e);nativeEye.SetGaze(4*Mathf.Sin(pathT*2*Mathf.PI));Apply();}
 public void SetPathFrame(int index){SetPath(((index%12)+12)%12/12f);}
 public void Apply(){nativeEye.Apply();if(block==null){block=new MaterialPropertyBlock();count=nativeEye.face.sharedMaterials.Length;}lastHeadToWorld=nativeEye.head.localToWorldMatrix;lastWorldToHead=lastHeadToWorld.inverse;for(int i=0;i<count;i++){nativeEye.face.GetPropertyBlock(block,i);block.SetFloat("_E162ApertureEnabled",apertureEnabled?1:0);block.SetVector("_E162ApertureScale",scale);block.SetVector("_E162Centre0",centreHead0);block.SetVector("_E162Centre1",centreHead1);block.SetMatrix("_E162HeadToWorld",lastHeadToWorld);block.SetMatrix("_E162WorldToHead",lastWorldToHead);nativeEye.face.SetPropertyBlock(block,i);}}
 void Start(){SetPose(poseIndex);}void LateUpdate(){if(!Application.isPlaying)return;if(playing){elapsed+=Time.unscaledDeltaTime*speed;if(continuous)SetPath(elapsed/cycleSeconds);else if(elapsed>=cycleSeconds/3){elapsed%=cycleSeconds/3;SetPose(poseIndex+1);}}Apply();}
 void OnGUI(){if(!Application.isPlaying)return;float y=Screen.height-58;GUI.Box(new Rect(8,y,Mathf.Min(528,Screen.width-16),50),"");if(GUI.Button(new Rect(14,y+5,65,22),playing?"Pause":"Play"))playing=!playing;if(GUI.Button(new Rect(84,y+5,50,22),"0.25x"))speed=.25f;if(GUI.Button(new Rect(139,y+5,38,22),"1x"))speed=1;if(GUI.Button(new Rect(182,y+5,32,22),"<")){playing=false;SetPose(poseIndex-1);}if(GUI.Button(new Rect(219,y+5,32,22),">")){playing=false;SetPose(poseIndex+1);}GUI.Label(new Rect(260,y+6,250,20),"Aperture input 1.20 / 1.15 test");GUI.Label(new Rect(14,y+29,510,18),"Original eye RGB / real hair depth / art review HOLD");}
}
